<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/db.php';
header('Cache-Control: no-store');header('X-Robots-Tag: noindex, nofollow');header('X-Frame-Options: DENY');header('X-Content-Type-Options: nosniff');header("Content-Security-Policy: default-src 'self'; img-src 'self' https://upload.wikimedia.org data:; style-src 'self' 'unsafe-inline'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'");
ini_set('session.use_strict_mode','1');session_set_cookie_params(['lifetime'=>0,'path'=>'/admin/','secure'=>true,'httponly'=>true,'samesite'=>'Strict']);session_start();
$_SESSION['csrf']??=bin2hex(random_bytes(32));$csrf=$_SESSION['csrf'];$password=config('QWANTA_ADMIN_PASSWORD')?:'';$ready=strlen($password)>=16&&dbConfigured();if(!$ready){error_log('Qwanta admin configuration: password='.(strlen($password)>=16?'valid':($password===''?'missing':'too short')).'; database_url='.(dbConfigured()?'present':'missing'));}$error=(string)($_SESSION['notice']??'');unset($_SESSION['notice']);$message='';
$logged=isset($_SESSION['admin'],$_SESSION['last'])&&hash_equals(hash('sha256',$password),$_SESSION['admin'])&&time()-$_SESSION['last']<3600;
if($logged)$_SESSION['last']=time();
function field(string $key,int $max,bool $required=false): string{$v=$_POST[$key]??'';if(!is_string($v))throw new RuntimeException('Invalid input');$v=trim($v);if(strlen($v)>$max||($required&&$v===''))throw new RuntimeException('Check required fields and length limits');return $v;}
function redirect(string $query=''): never{header('Location: /admin/'.$query, true,303);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!is_string($_POST['csrf']??null)||!hash_equals($csrf,$_POST['csrf'])){
 $oversize=empty($_POST)&&empty($_FILES)&&(int)($_SERVER['CONTENT_LENGTH']??0)>8388608;
 error_log('Qwanta admin form rejected: '.($oversize?'request too large':'session token missing or expired'));
 $_SESSION['notice']=$oversize?'The upload was too large. Please choose a JPG, PNG or WebP image under 2 MB.':'Your form session expired or the website was restarted. Please sign in again if needed and retry. No changes were saved.';
 header('Location: /admin/?tab=products',true,303);exit;
 }
 $action=$_POST['action']??'';
 if($action==='logout'){session_destroy();redirect();}
 if($ready){
 try{
 $db=db();
 if($action==='login'){
 $ip=iphash();$now=time();$db->beginTransaction();lock($db,784827);$db->prepare('DELETE FROM q_login_attempts WHERE created<?')->execute([$now-900]);$q=$db->prepare('SELECT COUNT(*) FROM q_login_attempts WHERE iphash=?');$q->execute([$ip]);if((int)$q->fetchColumn()>=8){$db->rollBack();unlock($db,784827);throw new RuntimeException('Too many attempts. Try again later.');}
 $db->prepare('INSERT INTO q_login_attempts VALUES (?,?)')->execute([$ip,$now]);$db->commit();unlock($db,784827);
 if(!hash_equals($password,field('password',512,true)))throw new RuntimeException('Incorrect password.');
 session_regenerate_id(true);$_SESSION['admin']=hash('sha256',$password);$_SESSION['last']=$now;$_SESSION['csrf']=bin2hex(random_bytes(32));redirect();
 }
 if(!$logged){$_SESSION['notice']='Your login session expired. Please sign in again and retry. No changes were saved.';redirect();}
 if($action==='impact'){
 $shipments=field('shipments',12,true);$revenue=field('revenue_inr',12,true);
 if(!preg_match('/^[0-9]{1,12}$/D',$shipments)||!preg_match('/^[0-9]{1,12}$/D',$revenue))throw new RuntimeException('Enter non-negative whole numbers (up to 12 digits).');
 saveImpact($db,(int)$shipments,(int)$revenue);redirect('?tab=impact&saved=1');
 }
 if($action==='category'){$name=field('category',80,true);if(strcasecmp($name,'All products')===0)throw new RuntimeException('This category name is reserved.');$db->prepare('INSERT INTO q_categories (name) VALUES (?) ON DUPLICATE KEY UPDATE name=name')->execute([$name]);redirect('?tab=categories&saved=1');}
 if($action==='save'){
 $id=filter_var($_POST['id']??'',FILTER_VALIDATE_INT);$name=field('name',100,true);if(strcasecmp($name,'Other product')===0)throw new RuntimeException('This name is reserved.');
 $category=field('category',80,true);$description=field('description',600,true);$spec=field('specifications',600);
 $fields=[$name,$category,$description,$spec,field('origin',100),field('packaging',300),field('moq',100),field('lead_time',100),field('price',100),field('availability',150),isset($_POST['published'])?1:0,isset($_POST['featured'])?1:0];
 $db->beginTransaction();
 if($id!==false){$q=$db->prepare('UPDATE q_products SET name=?,category=?,description=?,specifications=?,origin=?,packaging=?,moq=?,lead_time=?,price=?,availability=?,published=?,featured=? WHERE id=?');$q->execute([...$fields,$id]);if(!$q->rowCount()){$check=$db->prepare('SELECT id FROM q_products WHERE id=?');$check->execute([$id]);if($check->fetchColumn()===false)throw new RuntimeException('Product not found');}}
 else{$q=$db->prepare('INSERT INTO q_products(name,category,description,specifications,origin,packaging,moq,lead_time,price,availability,published,featured) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute($fields);$id=(int)$db->lastInsertId();}
 if(isset($_FILES['image'])&&$_FILES['image']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['image'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>2097152||!is_uploaded_file($f['tmp_name']))throw new RuntimeException('Upload a JPG, PNG or WebP image under 2 MB.');
 $info=@getimagesize($f['tmp_name']);$mime=$info['mime']??'';if(!in_array($mime,['image/jpeg','image/png','image/webp'],true)||$info[0]*$info[1]>16000000)throw new RuntimeException('Unsupported image or dimensions.');
 $db->prepare("UPDATE q_products SET image_data=?,image_mime=?,local='',url='',source='',author='',license='' WHERE id=?")->execute([base64_encode(file_get_contents($f['tmp_name'])),$mime,$id]);}
 $db->commit();redirect('?tab=products&saved=1');
 }
 if($action==='visibility'||$action==='delete'){$id=filter_var($_POST['id']??'',FILTER_VALIDATE_INT);if($id===false)throw new RuntimeException('Invalid product');if($action==='delete'){if(($_POST['confirm']??'')!=='yes')throw new RuntimeException('Confirm deletion first.');$db->prepare('DELETE FROM q_products WHERE id=?')->execute([$id]);}else{$db->prepare('UPDATE q_products SET published=NOT published WHERE id=?')->execute([$id]);}redirect('?tab=products&saved=1');}
 if($action==='status'){$status=field('status',30,true);if(!in_array($status,['New','In progress','Quoted','Closed'],true))throw new RuntimeException('Invalid status');$db->prepare('UPDATE q_enquiries SET status=? WHERE reference=?')->execute([$status,field('reference',40,true)]);redirect('?tab=enquiries&saved=1');}
 }catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();$error=$e instanceof PDOException?'Unable to save. Check for duplicate product names or database availability.':($e instanceof RuntimeException?$e->getMessage():'Request failed.');}
 }
}
$tab=$_GET['tab']??'overview';if(!in_array($tab,['overview','products','categories','enquiries','edit','impact'],true))$tab='overview';
$rows=[];$cats=[];$enquiries=[];$edit=null;$impact=['shipments'=>0,'revenue_inr'=>0];
if($ready&&$logged){try{$db=db();$rows=products($db,true);if($tab==='impact')$impact=impact($db);$cats=$db->query('SELECT name FROM q_categories ORDER BY name')->fetchAll(PDO::FETCH_COLUMN);$enquiries=$db->query('SELECT reference,created,payload,status FROM q_enquiries ORDER BY created DESC LIMIT 200')->fetchAll();if(isset($_GET['id'])&&filter_var($_GET['id'],FILTER_VALIDATE_INT)!==false){foreach($rows as $r)if((int)$r['id']===(int)$_GET['id'])$edit=$r;}}catch(Throwable $e){$error='Database temporarily unavailable.';}}
function hidden(string $csrf,string $action):void{echo '<input type="hidden" name="csrf" value="'.esc($csrf).'"><input type="hidden" name="action" value="'.esc($action).'">';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Qwanta | Seller dashboard</title><style>
*{box-sizing:border-box}body{margin:0;background:#0c0e20;color:#f3f2fc;font:15px/1.55 system-ui,sans-serif}a{color:#c3b3ff;text-decoration:none}a:hover{text-decoration:underline}header{border-bottom:1px solid #ffffff18;padding:18px clamp(18px,4vw,48px);display:flex;align-items:center;justify-content:space-between;gap:12px}header img{width:42px;border-radius:6px;vertical-align:middle;margin-right:10px}.brand{font-weight:750;color:#fff;letter-spacing:1px}.shell{max-width:1450px;margin:auto;display:grid;grid-template-columns:210px minmax(0,1fr);gap:28px;padding:32px clamp(18px,4vw,48px)}nav{display:flex;flex-direction:column;gap:8px}nav a{padding:12px 15px;border-radius:8px;color:#c7c4d8}nav a.active{background:#2b2547;color:#eee7ff}main{min-width:0}h1{font-size:clamp(25px,4vw,38px);letter-spacing:-1px;margin:0 0 5px}h2{font-size:20px;margin:0 0 15px}p{color:#b9b7ce;margin:5px 0 15px}.panel,.metric{background:#15172d;border:1px solid #ffffff17;border-radius:14px;padding:clamp(16px,2vw,25px);margin-bottom:18px}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:24px}.metric strong{display:block;font-size:32px;color:#c6b5ff}.metric span{font-size:13px;color:#aaa7c2}.row{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.btn,button{font:inherit;border:0;border-radius:8px;padding:10px 16px;min-height:42px;color:white;background:linear-gradient(115deg,#7659d8,#6587e7);cursor:pointer;display:inline-flex;align-items:center;justify-content:center;font-weight:650}.secondary{background:#22253e;color:#d9d2ff}.danger{background:#482c3d}.formgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}label{display:block;color:#d1cfe2;font-size:13px}input:not([type=checkbox]),textarea,select{display:block;width:100%;margin-top:6px;padding:12px;border-radius:8px;border:1px solid #ffffff25;background:#0e1024;color:white;font:inherit;min-width:0}input[type=checkbox]{accent-color:#a58bf7;width:18px;height:18px;vertical-align:middle}textarea{resize:vertical}.wide{grid-column:1/-1}.tablewrap{overflow-x:auto}table{border-collapse:collapse;width:100%;text-align:left;min-width:640px}th,td{padding:13px 10px;border-bottom:1px solid #ffffff15;vertical-align:middle}th{color:#aba7c7;font-size:12px;font-weight:600}td{font-size:14px}.status{font-size:12px;color:#c4b5ff}.alert{padding:14px;color:#f6c6c6;background:#3a2134;border:1px solid #a75a7466;border-radius:8px;margin-bottom:18px}.success{color:#b8e6ce;background:#16332d}.inline{display:inline}.login{max-width:440px;margin:12vh auto;padding:18px}.login button{width:100%;margin-top:18px}.muted{font-size:12px;color:#aaa7c0}.rfq{border-top:1px solid #ffffff14;padding:20px 0}.rfq dl{display:grid;grid-template-columns:minmax(110px,1fr) 3fr;gap:7px;font-size:14px;margin:15px 0}.rfq dt{color:#b4b0c9}.rfq dd{margin:0;overflow-wrap:anywhere;white-space:pre-wrap}.actions{display:flex;flex-wrap:wrap;gap:8px}.actions form{margin:0}.upload-note{font-size:12px;color:#b9b7ce}.check{display:flex;gap:10px;align-items:center}.preview{max-height:120px;max-width:160px;object-fit:contain;border-radius:8px}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid #b39aff;outline-offset:3px}@media(max-width:760px){.shell{grid-template-columns:1fr;padding-top:18px;gap:14px}nav{flex-direction:row;overflow-x:auto;white-space:nowrap}nav a{padding:9px 12px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.formgrid{grid-template-columns:1fr}.metric strong{font-size:25px}.panel{padding:15px}} 
</style></head><body><header><a class="brand" href="/admin/"><img src="/logo.png" alt="">QWANTA ADMIN</a><div class="actions"><a class="btn secondary" href="/">View website</a><?php if($logged){?><form method="post"><?php hidden($csrf,'logout');?><button class="secondary">Sign out</button></form><?php }?></div></header>
<?php if(!$ready||!$logged){?><div class="login"><div class="panel"><h1>Seller dashboard</h1><p>Private access for Qwanta Global Sourcing.</p><?php if($error){?><p class="alert"><?=esc($error)?></p><?php }?><?php if(!$ready){?><p class="alert">Dashboard setup is not complete. Please contact the administrator.</p><?php }else{?><form method="post"><?php hidden($csrf,'login');?><label>Password<input name="password" type="password" autocomplete="current-password" required maxlength="512"></label><button>Sign in</button></form><?php }?></div></div><?php }else{?>
<div class="shell"><nav aria-label="Dashboard"><?php foreach(['overview'=>'Overview','products'=>'Products','categories'=>'Categories','enquiries'=>'Enquiries','impact'=>'Global Impact'] as $k=>$v){?><a class="<?=$tab===$k||($tab==='edit'&&$k==='products')?'active':''?>" href="?tab=<?=esc($k)?>"><?=esc($v)?></a><?php }?></nav><main>
