<?php }elseif($tab==='edit'){?><h1><?=$edit?'Edit product':'Add product'?></h1><p>Enter accurate specifications. Unconfirmed terms may be left as on enquiry.</p><div class="panel"><form method="post" enctype="multipart/form-data" class="formgrid"><?php hidden($csrf,'save');?><input type="hidden" name="id" value="<?=esc($edit['id']??'')?>"><label>Product name<input name="name" maxlength="100" required value="<?=esc($edit['name']??'')?>"></label><label>Category<select name="category" required><?php foreach($cats as $c){?><option <?=($edit['category']??'')===$c?'selected':''?> value="<?=esc($c)?>"><?=esc($c)?></option><?php }?></select></label><label class="wide">Description<textarea name="description" rows="3" maxlength="600" required><?=esc($edit['description']??'')?></textarea></label><label class="wide">Grades and specifications<textarea name="specifications" rows="3" maxlength="600"><?=esc($edit['specifications']??'')?></textarea></label><?php foreach(['origin'=>['Origin','India',100],'packaging'=>['Packaging','On enquiry',300],'moq'=>['Minimum order','On enquiry',100],'lead_time'=>['Lead time','On enquiry',100],'price'=>['Price','On quotation',100],'availability'=>['Availability','Subject to confirmation',150]] as $k=>$a){?><label><?=esc($a[0])?><input name="<?=esc($k)?>" maxlength="<?=$a[2]?>" value="<?=esc($edit[$k]??$a[1])?>"></label><?php }?><label class="wide">Product photograph<input type="file" name="image" accept="image/jpeg,image/png,image/webp"><span class="upload-note">JPG, PNG or WebP up to 2 MB. Upload only photographs you own or have permission to use.</span></label><label class="check"><input type="checkbox" name="published" <?=!$edit||$edit['published']?'checked':''?>> Visible on public catalogue</label><label class="check"><input type="checkbox" name="featured" <?=!empty($edit['featured'])?'checked':''?>> Featured category priority</label><div class="wide actions"><button>Save product</button><a class="btn secondary" href="?tab=products">Cancel</a></div></form></div><?php if($edit){?><div class="panel"><h2>Delete product</h2><form method="post"><?php hidden($csrf,'delete');?><input type="hidden" name="id" value="<?=esc($edit['id'])?>"><label class="check"><input name="confirm" type="checkbox" value="yes" required> Permanently delete this product</label><button class="danger">Delete</button></form></div><?php }?>
